 const label=ring&&p.net!=='Havenbolme'?'O':p.type==='Local'?(p.pat==='S'?p.line:p.line.replace(/\d+/g,'')):p.pat==='AX'?'AX':p.pat+' '+p.line,plat=String(p.dir),platforms=Object.fromEntries(p.stops.map(n=>[n,plat]));
