 const targetScale=Math.min((W-96)/Math.max(36,right-left+16),(H-96)/Math.max(36,bottom-top+16));
 zoom=Math.max(1,Math.min(28,targetScale/fit));
 const sc=fit*zoom;
 const centreX=(left+right)/2,centreY=(top+bottom)/2;
 panX=(W/2-centreX*sc)-((W-graphWidth*sc)/2-minX*sc);
 panY=(H/2-centreY*sc)-((H-graphHeight*sc)/2-minY*sc);
